import { useState, useEffect } from "react";
import {
  Camera,
  Maximize2,
  Image as ImageIcon,
  Play,
  Square,
  Map,
  Plus,
  Pencil,
  Trash2,
  Eye,
  EyeOff,
  RotateCcw,
  CircleDashed,
  Droplets,
  Wrench,
} from "lucide-react";
import { Modal, ConfirmModal } from "@/components/common/Modal";
import { message } from "@/components/common/Message";
import { useRoamingPaths, setRoamingPaths } from "@/lib/roamingPaths";
import {
  getMaintenanceStatusMeta,
  getMaintenanceSystemColor,
  type MaintenanceSceneRecord,
} from "@/lib/maintenanceScenes";
import type { RoamingPath } from "@/types";
import damBg from "@/assets/db.png";
import panoramaBg from "@/assets/qj.png";
import equipmentBg from "@/assets/sb.png";
import pipelineBg from "@/assets/gd.png";
import { DevNote } from "@/components/devNotes/DevNote";

export interface PlayPathRequest {
  path: RoamingPath;
  token: number;
}

interface SelectionNode {
  title: string;
  code?: string;
  type?: string;
  children?: SelectionNode[];
}

interface Scene3DProps {
  viewMode: "overview" | "interior";
  focusMode: "panorama" | "equipment" | "pipeline" | "maintenance";
  selectedNode?: SelectionNode;
  onSelectNode?: (title: string, kind?: "equipment" | "pipeline") => void;
  onEnterInterior?: (focus: "panorama" | "equipment" | "pipeline") => void;
  /** 已开启水流的管路系统名（单个或系统粒度控制，无全局开关） */
  waterOnSystems?: string[];
  onWaterSystemToggle?: (name: string) => void;
  /** 大屏右侧或后台发起的路线播放请求 */
  playPathRequest?: PlayPathRequest | null;
  /** 当前展示的检修场景（为空时提示先选择场景） */
  maintenanceScene?: MaintenanceSceneRecord | null;
  /** 打开检修场景选择弹窗 */
  onOpenMaintenancePicker?: () => void;
}

type FloorKey =
  | "all"
  | "generator"
  | "busbar"
  | "turbine"
  | "spiral"
  | "drafttube";

const sceneNames: Record<string, string> = {
  "overview-panorama": "工程总览",
  "interior-panorama": "厂房全景",
  "interior-equipment": "设备总览",
  "interior-pipeline": "管路总览",
  "interior-maintenance": "检修场景",
};

// 设备分布数据
const equipmentPoints = [
  { x: 20, y: 30, name: "1#水泵水轮机", color: "#36cfc9", status: "running", data: "温度:42.3℃ 振动:2.1mm/s 出力:156MW" },
  { x: 45, y: 35, name: "2#水泵水轮机", color: "#36cfc9", status: "running", data: "温度:41.8℃ 振动:1.9mm/s 出力:152MW" },
  { x: 70, y: 40, name: "1#发电电动机", color: "#ffc53d", status: "running", data: "电流:3800A 温度:62℃ 功率:158MW" },
  { x: 30, y: 55, name: "1#技术供水泵", color: "#40a9ff", status: "running", data: "流量:320m³/h 压力:0.8MPa" },
  { x: 55, y: 60, name: "1#主变压器", color: "#73d13d", status: "running", data: "油温:58℃ 负载率:78%" },
  { x: 75, y: 25, name: "1#低压空压机", color: "#ff85c0", status: "warning", data: "压力:0.65MPa ⚠ 振动:4.2mm/s" },
  { x: 15, y: 65, name: "进水口闸门", color: "#b37feb", status: "running", data: "开度:100% 流量:1280m³/s" },
  { x: 85, y: 55, name: "1#开关柜", color: "#ff7a45", status: "running", data: "电压:220kV 电流:1800A" },
  { x: 40, y: 20, name: "1#进水阀", color: "#5cdbd3", status: "running", data: "开度:85% 压差:0.12MPa" },
  { x: 65, y: 70, name: "2#技术供水泵", color: "#40a9ff", status: "running", data: "流量:315m³/h 压力:0.78MPa" },
];

// 管路系统数据
export const pipelineSystems = [
  { name: "技术供水主管", y: 25, color: "blue", width: "70%", data: "流量:320m³/h 压力:0.8MPa" },
  { name: "排水主管", y: 38, color: "green", width: "60%", data: "流量:180m³/h 液位:正常" },
  { name: "气系统主管", y: 51, color: "yellow", width: "65%", data: "压力:0.65MPa 温度:28℃" },
  { name: "透平油主管", y: 64, color: "orange", width: "55%", data: "流量:45m³/h 油温:58℃" },
  { name: "消防水主管", y: 77, color: "red", width: "50%", data: "压力:0.5MPa 就绪" },
];

// 设备/管件 → 所属管路系统（用于单体水流控制）
const PIPELINE_KEYWORDS: Array<[string, string]> = [
  ["技术供水", "技术供水主管"],
  ["供水", "技术供水主管"],
  ["排水", "排水主管"],
  ["气系统", "气系统主管"],
  ["空压", "气系统主管"],
  ["透平油", "透平油主管"],
  ["消防", "消防水主管"],
  ["进水阀", "技术供水主管"],
  ["闸门", "技术供水主管"],
];

export function resolvePipelineSystem(title: string): string | undefined {
  if (pipelineSystems.some((pipe) => pipe.name === title)) return title;
  return PIPELINE_KEYWORDS.find(([keyword]) => title.includes(keyword))?.[1];
}

export function Scene3D({
  viewMode,
  focusMode,
  selectedNode,
  onSelectNode,
  onEnterInterior,
  waterOnSystems = [],
  onWaterSystemToggle,
  playPathRequest = null,
  maintenanceScene = null,
  onOpenMaintenancePicker,
}: Scene3DProps) {
  const [fps, setFps] = useState(60);
  const [roamingMode, setRoamingMode] = useState<"none" | "free" | "path">(
    "none"
  );
  const [showPathModal, setShowPathModal] = useState(false);
  const pathList = useRoamingPaths();
  const [deletePathId, setDeletePathId] = useState<number | null>(null);
  const [recording, setRecording] = useState(false);
  const [sceneTransition, setSceneTransition] = useState(false);
  const [activeFloor, setActiveFloor] = useState<FloorKey>("all");

  // 显隐 / 透明度控制
  const [hiddenNames, setHiddenNames] = useState<string[]>([]);
  const [opacityMap, setOpacityMap] = useState<Record<string, number>>({});

  const isNameVisible = (name: string) => !hiddenNames.includes(name);

  const getOpacity = (name: string) => opacityMap[name] ?? 1;

  // 水流按管路系统单独开关，默认全部静止
  const isWaterFlowing = (systemName: string) =>
    waterOnSystems.includes(systemName);

  // 后台/侧栏发起的路线播放
  useEffect(() => {
    if (!playPathRequest) return;
    setRoamingMode("path");
    setShowPathModal(false);
    message.info(
      `实际项目中：将按“${playPathRequest.path.name}”的关键帧自动飞行，依次经过设定对象，并按各节点设置的朝向、速度和停留时长播放。`
    );
  }, [playPathRequest]);


  // 场景切换过渡动画
  useEffect(() => {
    setSceneTransition(true);
    if (viewMode === "interior" && focusMode === "panorama") {
      setActiveFloor("all");
    }
    const timer = setTimeout(() => setSceneTransition(false), 1200);
    return () => clearTimeout(timer);
  }, [viewMode, focusMode]);

  // 模拟FPS波动
  useEffect(() => {
    const timer = setInterval(() => {
      setFps(58 + Math.floor(Math.random() * 5));
    }, 2000);
    return () => clearInterval(timer);
  }, []);

  // 厂房楼层信息
  const floorInfo: Record<FloorKey, { name: string; elevation: string }> = {
    all: { name: "全景视图", elevation: "全部楼层" },
    generator: { name: "发电机层", elevation: "EL.660.5m" },
    busbar: { name: "母线层", elevation: "EL.650.5m" },
    turbine: { name: "水轮机层", elevation: "EL.645.0m" },
    spiral: { name: "蜗壳层", elevation: "EL.630.0m" },
    drafttube: { name: "尾水管层", elevation: "EL.615.0m" },
  };

  // 当前场景名称
  const getCurrentSceneName = () => {
    if (viewMode === "interior") {
      if (focusMode === "panorama") return `厂房全景 - ${floorInfo[activeFloor].name}`;
      if (focusMode === "equipment") return `设备总览 - ${floorInfo[activeFloor].name}`;
      if (focusMode === "pipeline") return `管路总览 - ${floorInfo[activeFloor].name}`;
      if (focusMode === "maintenance")
        return `检修场景 - ${maintenanceScene?.name ?? "未选择"}`;
    }
    return sceneNames["overview-panorama"];
  };

  // 处理设备点点击
  const handleEquipmentClick = (eqName: string) => {
    if (onSelectNode) {
      onSelectNode(eqName, "equipment");
    }
    message.info(
      `实际项目中：三维相机将飞行定位并高亮“${eqName}”，右侧自动打开基础信息，可继续查看技术参数、运行数据和操作记录。`
    );
  };

  // 处理管路点击
  const handlePipelineClick = (pipeName: string) => {
    if (onSelectNode) {
      onSelectNode(pipeName, "pipeline");
    }
    message.info(
      `实际项目中：三维相机将沿管线定位并高亮“${pipeName}”，右侧自动打开基础信息、技术参数、运行数据和关联设备。`
    );
  };

  const handleFreeRoam = () => {
    if (roamingMode === "free") {
      setRoamingMode("none");
      message.info(
        "实际项目中：将退出第一人称自由漫游，保留当前相机位置并恢复常规模型交互。"
      );
    } else {
      setRoamingMode("free");
      message.info(
        "实际项目中：将进入UE5第一人称自由漫游，可使用WASD移动、鼠标调整方向并滚轮控制移动速度。"
      );
    }
  };

  const handleStopRoam = () => {
    setRoamingMode("none");
    setRecording(false);
    message.info(
      "实际项目中：将停止当前漫游或录制，保留停止位置，并重新启用模型点选和属性查看。"
    );
  };

  const handlePlayPath = (path: RoamingPath) => {
    setRoamingMode("path");
    setShowPathModal(false);
    message.info(
      `实际项目中：将按“${path.name}”的关键帧自动飞行，依次经过设定对象，并按各节点设置的朝向、速度和停留时长播放。`
    );
  };

  const handleStartRecord = () => {
    setRecording(true);
    setShowPathModal(false);
    message.info(
      "实际项目中：将开始记录相机位置、朝向和停留点；可使用WASD移动，完成后点击“停止录制”生成自定义路线。"
    );
  };

  const handleStopRecord = () => {
    setRecording(false);
    const newPath: RoamingPath = {
      id: Date.now(),
      name: `自定义路线${pathList.filter((p) => p.type === "custom").length + 1}`,
      type: "custom",
      createTime: new Date().toLocaleString("zh-CN"),
      duration: 60,
      description: "用户自定义录制路线",
    };
    setRoamingPaths([...pathList, newPath]);
    message.success(
      "已生成一条自定义路线并保存；实际项目中还将保存关键帧、相机朝向、停留时长和播放速度。"
    );
  };

  const handleDeletePath = () => {
    if (deletePathId !== null) {
      setRoamingPaths(pathList.filter((p) => p.id !== deletePathId));
      message.success("路径已删除");
      setDeletePathId(null);
    }
  };

  // ===== 选中对象/系统 → 可批量控制的目标集合 =====
  const selection = (() => {
    const node = selectedNode;
    const sceneNames = [
      ...equipmentPoints.map((item) => item.name),
      ...pipelineSystems.map((item) => item.name),
    ];
    if (!node) {
      return {
        names: [] as string[],
        systemName: undefined as string | undefined,
        isGroup: false,
      };
    }

    const isGroup =
      node.type === "system" || node.type === "usage" || !!node.children?.length;

    // 单个模型：只控制自身
    if (!isGroup) {
      const systemName = resolvePipelineSystem(node.title);
      return {
        names: sceneNames.includes(node.title)
          ? [node.title]
          : systemName
            ? [systemName]
            : [],
        systemName,
        isGroup: false,
      };
    }

    // 系统 / 分组：批量控制其下所有模型
    const titles: string[] = [];
    const walk = (item: SelectionNode) => {
      titles.push(item.title);
      item.children?.forEach(walk);
    };
    walk(node);

    const systemName =
      resolvePipelineSystem(node.title) ??
      titles.map((title) => resolvePipelineSystem(title)).find(Boolean);

    const names = new Set<string>();
    titles.forEach((title) => {
      if (sceneNames.includes(title)) names.add(title);
    });
    if (systemName) {
      pipelineSystems
        .filter((pipe) => pipe.name === systemName)
        .forEach((pipe) => names.add(pipe.name));
      equipmentPoints
        .filter((item) => resolvePipelineSystem(item.name) === systemName)
        .forEach((item) => names.add(item.name));
    }

    return { names: [...names], systemName, isGroup: true };
  })();

  const targetNames = selection.names;
  const hasTarget = targetNames.length > 0;
  const allTargetsVisible =
    hasTarget && targetNames.every((name) => !hiddenNames.includes(name));
  const currentOpacity = hasTarget ? (opacityMap[targetNames[0]] ?? 1) : 1;
  const waterOn =
    !!selection.systemName && waterOnSystems.includes(selection.systemName);

  const requireSelection = () => {
    if (hasTarget) return true;
    message.warning("请先在三维视口或结构树中选择设备、管件或系统");
    return false;
  };

  // 是否显示（单个或整组）
  const handleToggleVisible = () => {
    if (!requireSelection()) return;
    if (allTargetsVisible) {
      setHiddenNames((prev) => Array.from(new Set([...prev, ...targetNames])));
      message.success(
        selection.isGroup
          ? `已隐藏该系统下 ${targetNames.length} 个模型`
          : `已隐藏“${targetNames[0]}”，再次点击可恢复`
      );
      return;
    }
    setHiddenNames((prev) => prev.filter((name) => !targetNames.includes(name)));
    message.success(
      selection.isGroup ? "已恢复该系统全部模型显示" : "已恢复显示"
    );
  };

  // 透明度：不透明 → 半透明 → 淡显
  const OPACITY_STEPS = [1, 0.6, 0.3];

  const handleCycleOpacity = () => {
    if (!requireSelection()) return;
    const index = OPACITY_STEPS.findIndex(
      (value) => Math.abs(value - currentOpacity) < 0.01
    );
    const next = OPACITY_STEPS[(index + 1) % OPACITY_STEPS.length];
    setOpacityMap((prev) => {
      const draft = { ...prev };
      targetNames.forEach((name) => {
        draft[name] = next;
      });
      return draft;
    });
    message.success(
      `已设为${next === 1 ? "不透明" : next === 0.6 ? "半透明" : "淡显"}（${Math.round(
        next * 100
      )}%）`
    );
  };

  // 水流效果：按单个模型所属系统 / 整个系统控制
  const handleToggleWater = () => {
    if (!requireSelection()) return;
    if (!selection.systemName) {
      message.warning("当前对象不属于任何管路系统，没有水流效果");
      return;
    }
    onWaterSystemToggle?.(selection.systemName);
    message.success(
      waterOn
        ? `已关闭“${selection.systemName}”水流`
        : `已开启“${selection.systemName}”水流`
    );
  };

  const handleResetTools = () => {
    setHiddenNames([]);
    setOpacityMap({});
    message.info("已恢复全部模型显示和默认透明度");
  };

  // ===== 场景1：工程总览 - 水电站全景 =====
  const renderOverviewScene = () => (
    <div className="absolute inset-0">
      {/* 真实大坝背景图片 */}
      <div className="absolute inset-0">
        <img 
          src={damBg} 
          alt="乌江渡水电站大坝"
          className="w-full h-full object-cover"
          style={{ filter: "brightness(0.7) saturate(0.95)" }}
        />
        {/* 科技感遮罩层 */}
        <div className="absolute inset-0" style={{
          background: `
            linear-gradient(180deg, 
              rgba(10,22,40,0.5) 0%, 
              rgba(13,33,55,0.2) 30%, 
              rgba(13,33,55,0.2) 70%, 
              rgba(10,22,40,0.6) 100%
            )
          `
        }} />
        {/* 网格叠加 */}
        <div className="scene-grid absolute inset-0 opacity-20" />
      </div>

      {/* SVG叠加层 - 科技感元素 */}
      <div className="absolute inset-0 pointer-events-none">
        <svg viewBox="0 0 1200 700" className="w-full h-full" preserveAspectRatio="xMidYMid slice">
          <defs>
            {/* 网格滤镜 */}
            <filter id="glow">
              <feGaussianBlur stdDeviation="2" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
            <filter id="strongGlow">
              <feGaussianBlur stdDeviation="4" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
            {/* 水面波纹渐变 */}
            <linearGradient id="waterShine" x1="0%" y1="0%" x2="0%" y2="100%">
              <stop offset="0%" stopColor="#4a8ab0" stopOpacity="0.6" />
              <stop offset="100%" stopColor="#2a5a7a" stopOpacity="0" />
            </linearGradient>
            {/* 坝顶高光渐变 */}
            <linearGradient id="damHighlight" x1="0%" y1="0%" x2="0%" y2="100%">
              <stop offset="0%" stopColor="#ffffff" stopOpacity="0.3" />
              <stop offset="100%" stopColor="#ffffff" stopOpacity="0" />
            </linearGradient>
          </defs>

          {/* 科技感网格 - 背景参考线 */}
          <g opacity="0.08">
            {Array.from({ length: 12 }).map((_, i) => (
              <line key={`h${i}`} x1="0" y1={i * 60} x2="1200" y2={i * 60} stroke="#00b4ff" strokeWidth="0.5" />
            ))}
            {Array.from({ length: 20 }).map((_, i) => (
              <line key={`v${i}`} x1={i * 60} y1="0" x2={i * 60} y2="700" stroke="#00b4ff" strokeWidth="0.5" />
            ))}
          </g>

          {/* 水面波纹特效 - 上游水库区域（画面上部） */}
          <g opacity="0.4">
            {[0, 1, 2, 3, 4].map((i) => (
              <path key={i} 
                d={`M${-100 + i * 250},180 Q${100 + i * 250},170 ${300 + i * 250},180 T${500 + i * 250},180`} 
                fill="none" 
                stroke={i % 2 === 0 ? "#4a8ab0" : "#3a7a9a"} 
                strokeWidth="1"
              >
                <animate attributeName="d" 
                  values={`M${-100 + i * 250},180 Q${100 + i * 250},170 ${300 + i * 250},180 T${500 + i * 250},180;M${-100 + i * 250},180 Q${100 + i * 250},190 ${300 + i * 250},180 T${500 + i * 250},180;M${-100 + i * 250},180 Q${100 + i * 250},170 ${300 + i * 250},180 T${500 + i * 250},180`} 
                  dur="4s" 
                  repeatCount="indefinite" 
                />
              </path>
            ))}
          </g>

          {/* 坝顶高光线 - 画面中间 */}
          <g opacity="0.6">
            <line x1="350" y1="350" x2="850" y2="350" stroke="url(#damHighlight)" strokeWidth="2" />
            <line x1="350" y1="355" x2="850" y2="355" stroke="#4a7a9a" strokeWidth="0.5" strokeDasharray="4,2" opacity="0.5">
              <animate attributeName="stroke-dashoffset" values="0;12" dur="2s" repeatCount="indefinite" />
            </line>
          </g>

          {/* 溢洪道位置标记 - 画面中上部 */}
          <g opacity="0.7">
            {[0, 1, 2, 3, 4].map((i) => (
              <g key={i}>
                {/* 溢洪道矩形标记 */}
                <rect 
                  x={420 + i * 80} 
                  y="380" 
                  width="40" 
                  height="15" 
                  fill="#1a3a5a" 
                  stroke="#3a7a9a" 
                  strokeWidth="1"
                  rx="2"
                  opacity="0.6"
                />
                {/* 水流动画 */}
                <rect 
                  x={425 + i * 80} 
                  y="395" 
                  width="30" 
                  height="80" 
                  fill="#3a7a9a" 
                  rx="2"
                  opacity="0.4"
                >
                  <animate 
                    attributeName="y" 
                    values="395;455;395" 
                    dur={`${1.5 + i * 0.3}s`} 
                    repeatCount="indefinite" 
                  />
                  <animate 
                    attributeName="opacity" 
                    values="0.4;0.7;0.4" 
                    dur={`${1.5 + i * 0.3}s`} 
                    repeatCount="indefinite" 
                  />
                </rect>
              </g>
            ))}
          </g>

          {/* 数据点发光效果 - 关键位置 */}
          <g filter="url(#strongGlow)">
            {/* 大坝中心点 */}
            <circle cx="600" cy="420" r="6" fill="#00b4ff" opacity="0.8">
              <animate attributeName="opacity" values="0.8;1;0.8" dur="2s" repeatCount="indefinite" />
            </circle>
            <circle cx="600" cy="420" r="12" fill="none" stroke="#00b4ff" strokeWidth="1" opacity="0.5">
              <animate attributeName="r" values="6;25;6" dur="2.5s" repeatCount="indefinite" />
              <animate attributeName="opacity" values="0.5;0;0.5" dur="2.5s" repeatCount="indefinite" />
            </circle>
            
            {/* 上游水库点 */}
            <circle cx="400" cy="180" r="4" fill="#4dd0e1" opacity="0.7">
              <animate attributeName="opacity" values="0.7;1;0.7" dur="3s" repeatCount="indefinite" />
            </circle>
            
            {/* 厂房区域点 */}
            <circle cx="600" cy="500" r="5" fill="#7ad0a0" opacity="0.8">
              <animate attributeName="opacity" values="0.8;1;0.8" dur="2.5s" repeatCount="indefinite" />
            </circle>
            
            {/* 尾水渠点 */}
            <circle cx="600" cy="570" r="4" fill="#80d8ff" opacity="0.7">
              <animate attributeName="opacity" values="0.7;1;0.7" dur="2.8s" repeatCount="indefinite" />
            </circle>
          </g>

          {/* 装饰光晕 */}
          <ellipse cx="600" cy="420" rx="150" ry="60" fill="#00b4ff" opacity="0.03">
            <animate attributeName="opacity" values="0.03;0.08;0.03" dur="4s" repeatCount="indefinite" />
          </ellipse>
          <ellipse cx="400" cy="180" rx="80" ry="40" fill="#4dd0e1" opacity="0.02">
            <animate attributeName="opacity" values="0.02;0.06;0.02" dur="3.5s" repeatCount="indefinite" />
          </ellipse>
          <ellipse cx="600" cy="570" rx="100" ry="30" fill="#80d8ff" opacity="0.02">
            <animate attributeName="opacity" values="0.02;0.05;0.02" dur="3s" repeatCount="indefinite" />
          </ellipse>

          {/* 数据流连接线 */}
          <g opacity="0.3" strokeDasharray="4,4">
            <line x1="400" y1="180" x2="600" y2="420" stroke="#4dd0e1" strokeWidth="1">
              <animate attributeName="stroke-dashoffset" values="0;16" dur="2s" repeatCount="indefinite" />
            </line>
            <line x1="600" y1="420" x2="600" y2="570" stroke="#80d8ff" strokeWidth="1">
              <animate attributeName="stroke-dashoffset" values="0;16" dur="2.5s" repeatCount="indefinite" />
            </line>
            <line x1="600" y1="500" x2="800" y2="570" stroke="#7ad0a0" strokeWidth="1">
              <animate attributeName="stroke-dashoffset" values="0;16" dur="3s" repeatCount="indefinite" />
            </line>
          </g>

          {/* 画面四角装饰 */}
          <g opacity="0.4" stroke="#00b4ff" strokeWidth="2" fill="none">
            {/* 左上角 */}
            <path d="M10,10 L10,40 M10,10 L40,10" />
            {/* 右上角 */}
            <path d="M1190,10 L1190,40 M1190,10 L1160,10" />
            {/* 左下角 */}
            <path d="M10,690 L10,660 M10,690 L40,690" />
            {/* 右下角 */}
            <path d="M1190,690 L1190,660 M1190,690 L1160,690" />
          </g>
        </svg>
      </div>

      {/* 厂房标记 - 点击进入数字孪生厂区 */}
      <DevNote
        id="scene-overview-plant"
        title="坝后厂房标记点（工程总览）"
        summary="点击厂房标记从工程总览进入数字孪生厂区（厂房全景）"
        items={[
          { label: "数据来源", value: "静态文案：4台机组、总出力612.3MW、机组4/4运行" },
          { label: "交互逻辑", value: "点击 → onEnterInterior(\"panorama\")：viewMode 切为 interior、focusMode=panorama，提示“相机从工程总览飞行进入坝后厂房，加载建筑/设备/管网模型并默认定位发电机层”" },
          { label: "联动", value: "进入后中央展示厂房融合场景，出现楼层切换器（全景视图+五层），右侧保持统计信息3Tab（未选中对象）" },
          { label: "后续步骤", value: "正式系统：相机飞行过渡并流式加载 UE5 厂房场景资源" },
          { label: "权限", value: "大屏所有已登录用户可用" },
        ]}
        wrapClassName="absolute z-20 top-[50%] left-1/2 -translate-x-1/2"
      >
      <div
        className="cursor-pointer group"
        onClick={() => {
          if (onEnterInterior) {
            onEnterInterior("panorama" as any);
            message.info(
              "实际项目中：三维相机将从工程总览飞行进入坝后厂房，加载建筑、设备和管网模型，并默认定位发电机层。"
            );
          }
        }}
      >
        <div className="relative">
          <div className="w-8 h-8 rounded-full bg-green-400/30 animate-ping absolute -inset-2" />
          <div className="w-4 h-4 rounded-full bg-green-400 border-2 border-white shadow-lg shadow-green-400/50" />
          <div className="absolute top-6 left-1/2 -translate-x-1/2 whitespace-nowrap bg-black/75 backdrop-blur-sm px-3 py-1.5 border border-green-500/30 group-hover:border-green-400 transition-colors" style={{ borderRadius: 0 }}>
            <div className="text-xs text-green-300 font-medium">坝后厂房 (4台机组)</div>
            <div className="text-[10px] text-green-400/70 mt-0.5">总出力 612.3MW · 机组4/4运行</div>
          </div>
          <div className="absolute -bottom-5 left-1/2 -translate-x-1/2 text-[9px] text-blue-400/0 group-hover:text-blue-400 transition-colors whitespace-nowrap">
            点击进入内部 →
          </div>
        </div>
      </div>
      </DevNote>

      {/* 操作提示 */}
      <div className="absolute bottom-[5%] left-1/2 -translate-x-1/2 text-xs text-[#40A9FF]/70 bg-black/60 backdrop-blur-sm px-4 py-1.5 rounded-none border border-cyan-500/20 z-10">
        点击坝后厂房进入数字孪生厂区
      </div>
    </div>
  );

  // ===== 场景2/3：融合厂房内部视图 - 设备与管网共存 =====
  const renderFusionScene = () => {
    // 根据 focusMode 调整透明度
    // panorama: 设备和管网都显示
    // equipment: 设备高亮，管网淡化
    // pipeline: 管网高亮，设备淡化
    const equipmentHighlight = focusMode === "equipment" ? 1 : focusMode === "pipeline" ? 0.25 : 0.7;
    const pipelineHighlight = focusMode === "pipeline" ? 1 : focusMode === "equipment" ? 0.25 : 0.7;
    
    let titleText = "厂房全景视图";
    let subtitleText = "设备与管网融合展示 · 通过顶部导航切换视图";
    if (focusMode === "equipment") {
      titleText = "设备总览";
      subtitleText = "高亮显示设备分布，管网淡化 · 点击设备查看属性";
    } else if (focusMode === "pipeline") {
      titleText = "管路总览";
      subtitleText = "高亮显示管网系统，设备淡化 · 点击管路查看属性";
    }
    
    return (
    <div className="absolute inset-0">
      {/* 真实背景图片 - 根据 focusMode 切换 */}
      <div className="absolute inset-0">
        <img 
          src={focusMode === "equipment" ? equipmentBg : focusMode === "pipeline" ? pipelineBg : panoramaBg} 
          alt={titleText}
          className="w-full h-full object-cover"
          style={{ filter: "brightness(0.6) saturate(0.9)" }}
        />
        {/* 深色遮罩层 */}
        <div className="absolute inset-0" style={{
          background: "rgba(7, 11, 20, 0.55)"
        }} />
        {/* 科技感网格叠加 */}
        <div className="scene-grid absolute inset-0 opacity-15" />
      </div>

      {/* 场景标题 */}
      <div className="absolute top-[4%] left-1/2 -translate-x-1/2 text-center z-10">
        <div className="text-white text-base font-bold tracking-widest px-4 py-1" style={{ 
          textShadow: "0 0 10px rgba(64,169,255,0.8)",
          borderBottom: "1px solid rgba(64,169,255,0.3)",
        }}>
          {titleText}
        </div>
        <div className="text-[#40A9FF]/70 text-xs mt-1">{subtitleText}</div>
      </div>

      {/* 全景及五层模型切换 */}
      <DevNote
        id="scene-floor-switch"
        title="楼层切换器（全景视图/五层）"
        summary="厂房内一键切换全景或五层楼：发电机层/母线层/水轮机层/蜗壳层/尾水管层"
        items={[
          { label: "数据来源", value: "floorInfo 静态配置：发电机层 EL.660.5m、母线层 EL.650.5m、水轮机层 EL.645.0m、蜗壳层 EL.630.0m、尾水管层 EL.615.0m；activeFloor 状态记录当前楼层" },
          { label: "交互逻辑", value: "点击“全景视图”→ 恢复 all 展示全部楼层设备与管线；点击某层 → 相机垂直飞行至该层并只突出该层设备与管线（原型为 message 占位）；场景切换时（interior+panorama）自动重置为 all" },
          { label: "视觉联动", value: "激活楼层按钮高亮（bg-[#40A9FF]/20）；楼层分隔虚线随 activeFloor 高亮对应层带" },
          { label: "后续步骤", value: "正式系统：楼层切换由 UE5 相机控制并按楼层过滤模型显隐" },
          { label: "权限", value: "大屏所有已登录用户可用" },
        ]}
        wrapClassName="absolute top-[12%] left-1/2 -translate-x-1/2 z-20"
      >
      <div className="flex gap-1">
        <button
          onClick={() => {
            setActiveFloor("all");
            message.info("实际项目中：三维相机将恢复厂房全景视角，并显示全部楼层的设备和管线。");
          }}
          className={`px-3 py-1.5 text-xs transition-colors rounded-none ${
            activeFloor === "all"
              ? "bg-[#40A9FF]/20 text-white border border-[#40A9FF]"
              : "bg-black/50 text-[#8a94a6] border border-[#40A9FF]/20 hover:text-white hover:border-[#40A9FF]/50"
          }`}
        >
          全景视图
        </button>
        {(["generator", "busbar", "turbine", "spiral", "drafttube"] as const).map((floor) => (
          <button
            key={floor}
            onClick={() => {
              setActiveFloor(floor);
              message.info(
                `实际项目中：三维相机将垂直飞行至${floorInfo[floor].name}（${floorInfo[floor].elevation}），并只突出该层设备和管线。`
              );
            }}
            className={`px-3 py-1.5 text-xs transition-colors rounded-none ${
              activeFloor === floor
                ? "bg-[#40A9FF]/20 text-white border border-[#40A9FF]"
                : "bg-black/50 text-[#8a94a6] border border-[#40A9FF]/20 hover:text-white hover:border-[#40A9FF]/50"
            }`}
          >
            {floorInfo[floor].name} ({floorInfo[floor].elevation})
          </button>
        ))}
      </div>
      </DevNote>

      {/* 厂房融合视图 - 透明覆盖层 */}
      <div className="absolute inset-0 flex items-center justify-center" style={{ paddingTop: "16%" }}>
        <div className="relative" style={{ width: "90%", height: "74%" }}>
          {/* 厂房建筑（外框 + 楼层分隔） */}
          <div className="absolute inset-0 pointer-events-none">
          {/* 厂房外框 - 透明边框 */}
          <div className="absolute inset-0 rounded-none" style={{ 
            border: "1px solid rgba(64,169,255,0.25)", 
            background: "transparent",
          }} />

          {/* 五层分隔及楼层标签 */}
          {[
            { floor: "generator", top: 0 },
            { floor: "busbar", top: 20 },
            { floor: "turbine", top: 40 },
            { floor: "spiral", top: 60 },
            { floor: "drafttube", top: 80 },
          ].map((item) => (
            <div
              key={item.floor}
              className="absolute left-0 right-0"
              style={{
                top: `${item.top}%`,
                borderTop:
                  item.top === 0
                    ? "none"
                    : "1px dashed rgba(64,158,255,0.3)",
              }}
            >
              <span className="absolute left-3 top-1 text-xs text-[#40A9FF]/70 font-medium">
                {floorInfo[item.floor as FloorKey].name} ({floorInfo[item.floor as FloorKey].elevation})
              </span>
            </div>
          ))}

          {/* 当前楼层高亮指示；全景模式不遮挡分层模型 */}
          {activeFloor !== "all" && (
            <div
              className="absolute left-0 right-0 transition-all"
              style={{
                top: `${
                  {
                    generator: 0,
                    busbar: 20,
                    turbine: 40,
                    spiral: 60,
                    drafttube: 80,
                  }[activeFloor]
                }%`,
                height: "20%",
                background:
                  activeFloor === "generator"
                    ? "rgba(24,144,255,0.10)"
                    : activeFloor === "busbar"
                      ? "rgba(114,46,209,0.10)"
                      : activeFloor === "turbine"
                        ? "rgba(82,196,26,0.10)"
                        : activeFloor === "spiral"
                          ? "rgba(250,173,20,0.10)"
                          : "rgba(24,144,255,0.12)",
                borderTop: "2px solid rgba(64,169,255,0.65)",
                borderBottom: "2px solid rgba(64,169,255,0.35)",
                pointerEvents: "none",
              }}
            />
          )}
          </div>

          {/* ========== 第1层：管网系统（底层） ========== */}
          <div className="absolute inset-0" style={{ opacity: pipelineHighlight, transition: "opacity 0.5s" }}>
            {pipelineSystems.map((pipe) => {
              if (!isNameVisible(pipe.name)) return null;
              const flowing = isWaterFlowing(pipe.name);
              return (
              <div
                key={pipe.name}
                className={`absolute left-[6%] right-[6%] ${flowing ? `pipe-flow-${pipe.color}` : ""} ${focusMode === "pipeline" ? "cursor-pointer group" : ""}`}
                style={{ top: `${pipe.y}%`, opacity: getOpacity(pipe.name) }}
                onClick={() => focusMode === "pipeline" && handlePipelineClick(pipe.name)}
              >
                <div className="relative h-8 rounded" style={{
                  width: pipe.width,
                  background: pipe.color === "blue" ? "rgba(24,144,255,0.15)" :
                             pipe.color === "green" ? "rgba(82,196,26,0.15)" :
                             pipe.color === "yellow" ? "rgba(250,173,20,0.15)" :
                             pipe.color === "orange" ? "rgba(255,133,20,0.15)" :
                             "rgba(255,77,79,0.15)",
                  border: `1px solid ${pipe.color === "blue" ? "rgba(24,144,255,0.4)" :
                             pipe.color === "green" ? "rgba(82,196,26,0.4)" :
                             pipe.color === "yellow" ? "rgba(250,173,20,0.4)" :
                             pipe.color === "orange" ? "rgba(255,133,20,0.4)" :
                             "rgba(255,77,79,0.4)"}`,
                  overflow: "hidden",
                  boxShadow: focusMode === "pipeline" ? `0 0 12px ${pipe.color === "blue" ? "rgba(24,144,255,0.3)" : pipe.color === "green" ? "rgba(82,196,26,0.3)" : "rgba(250,173,20,0.3)"}` : "none",
                }}>
                  {flowing && <div className="pipe-flow absolute inset-0" />}
                </div>
                {/* 管路标签 + 测点数据气泡 */}
                <div className="absolute -top-5 left-2 text-xs font-medium"
                  style={{
                    color: pipe.color === "blue" ? "#1890ff" : pipe.color === "green" ? "#52c41a" : pipe.color === "yellow" ? "#faad14" : "#ff8520",
                    textShadow: "0 0 4px rgba(0,0,0,0.8)",
                    opacity: focusMode === "pipeline" ? 1 : 0.45,
                    transition: "opacity 0.5s",
                  }}
                >
                  <div>{pipe.name}</div>
                  <div className="text-[9px] opacity-80" style={{ color: "#c5d0de" }}>{pipe.data}</div>
                </div>
              </div>
              );
            })}
          </div>

          {/* ========== 第2层：设备分布（顶层） ========== */}
          <div className="absolute inset-0" style={{ opacity: equipmentHighlight, transition: "opacity 0.5s" }}>
            {equipmentPoints.map((eq) => {
              if (!isNameVisible(eq.name)) return null;
              return (
              <div
                key={eq.name}
                className={`absolute ${focusMode === "equipment" ? "cursor-pointer group" : ""}`}
                style={{ left: `${eq.x}%`, top: `${eq.y}%`, transform: "translate(-50%, -50%)", opacity: getOpacity(eq.name) }}
                onClick={() => focusMode === "equipment" && handleEquipmentClick(eq.name)}
              >
                {/* 光环 */}
                <div className="absolute rounded-full equipment-ripple" style={{
                  width: focusMode === "equipment" ? "32px" : "24px", height: focusMode === "equipment" ? "32px" : "24px",
                  background: eq.color,
                  opacity: focusMode === "equipment" ? 0.4 : 0.2,
                  left: focusMode === "equipment" ? "-16px" : "-12px", top: focusMode === "equipment" ? "-16px" : "-12px",
                }} />
                {/* 设备点 */}
                <div className={`equipment-dot rounded-full transition-transform ${focusMode === "equipment" ? "group-hover:scale-150" : ""}`} style={{
                  width: focusMode === "equipment" ? "16px" : "12px", height: focusMode === "equipment" ? "16px" : "12px",
                  background: eq.color,
                  boxShadow: focusMode === "equipment" 
                    ? `0 0 20px ${eq.color}, 0 0 10px ${eq.color}` 
                    : `0 0 8px ${eq.color}`,
                  border: "2px solid rgba(255,255,255,0.6)",
                }} />
                {/* 设备标签 - 显示测点数据气泡 */}
                  <div className="equipment-label absolute left-5 top-1/2 -translate-y-1/2 whitespace-nowrap px-2 py-1 rounded text-xs"
                    style={{
                      background: "rgba(0,0,0,0.85)",
                      color: eq.color,
                      border: `1px solid ${eq.color}80`,
                      fontWeight: 600,
                      minWidth: "140px",
                    }}
                  >
                    <div className="flex items-center gap-1">
                      {eq.name}
                      <span className="text-[9px] opacity-70">
                        {eq.status === "running" ? "●运行" : eq.status === "warning" ? "▲告警" : "○停机"}
                      </span>
                    </div>
                    <div className="text-[9px] mt-0.5 opacity-80 leading-tight" style={{ color: eq.status === "warning" ? "#ff7875" : "#c5d0de" }}>
                      {eq.data}
                    </div>
                  </div>
              </div>
              );
            })}
          </div>

          {/* ========== 图例与信息层 ========== */}
          {/* 设备图例 */}
          {focusMode === "equipment" && (
            <div className="absolute bottom-3 right-3 flex flex-col gap-1.5 p-2.5 rounded-nonebg-black/60 border border-blue-500/30 backdrop-blur-sm">
              <div className="text-[10px] text-blue-400/70 mb-1">设备状态图例</div>
              {[
                { label: "运行中", color: "#36cfc9", count: "148台" },
                { label: "告警", color: "#ff85c0", count: "2台" },
                { label: "停机", color: "#b37feb", count: "6台" },
              ].map((item) => (
                <div key={item.label} className="flex items-center gap-2 text-[10px]">
                  <span className="w-2.5 h-2.5 rounded-full" style={{ background: item.color, boxShadow: `0 0 6px ${item.color}` }} />
                  <span style={{ color: item.color }}>{item.label}</span>
                  <span className="text-blue-400/60">{item.count}</span>
                </div>
              ))}
            </div>
          )}

          {/* 管路图例 */}
          {focusMode === "pipeline" && (
            <div className="absolute bottom-3 right-3 flex flex-col gap-1.5 p-2.5 rounded-nonebg-black/60 border border-blue-500/30 backdrop-blur-sm">
              <div className="text-[10px] text-blue-400/70 mb-1">管路系统图例</div>
              {[
                { label: "技术供水", color: "#1890ff", count: "4,280m" },
                { label: "排水系统", color: "#52c41a", count: "2,150m" },
                { label: "气系统", color: "#faad14", count: "1,820m" },
                { label: "透平油", color: "#ff8520", count: "2,330m" },
                { label: "消防水", color: "#ff4d4f", count: "2,000m" },
              ].map((item) => (
                <div key={item.label} className="flex items-center gap-2 text-[10px]">
                  <span className="w-4 h-1.5 rounded" style={{ background: item.color, boxShadow: `0 0 4px ${item.color}` }} />
                  <span style={{ color: item.color }}>{item.label}</span>
                  <span className="text-blue-400/60">{item.count}</span>
                </div>
              ))}
            </div>
          )}

          {/* 操作提示 */}
          <div className="absolute bottom-3 left-3 text-[10px] text-blue-400/70 bg-black/60 px-2 py-1 rounded-nonebackdrop-blur-sm">
            {focusMode === "equipment" 
              ? "点击设备查看属性详情" 
              : focusMode === "pipeline" 
                ? "点击管路查看属性详情" 
                : "厂房全景视图 · 可通过顶部导航切换设备/管路总览"}
          </div>

          {/* 楼层标签 */}
          <div className="absolute -bottom-6 left-1/2 -translate-x-1/2 text-xs text-[#40A9FF]/60">坝后厂房 - {floorInfo[activeFloor].name}</div>
        </div>
      </div>
    </div>
  );
};

  // ===== 检修场景：只展示所选管路/阀门，并以立牌标注状态 =====
  const renderMaintenanceScene = () => {
    if (!maintenanceScene) {
      return (
        <div className="absolute inset-0">
          <img
            src={panoramaBg}
            alt="检修场景"
            className="w-full h-full object-cover"
            style={{ filter: "brightness(0.35) saturate(0.7)" }}
          />
          <div className="absolute inset-0" style={{ background: "rgba(7, 11, 20, 0.7)" }} />
          <div className="scene-grid absolute inset-0 opacity-15" />
          <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 z-10">
            <div className="text-white text-lg font-bold tracking-widest">
              尚未选择检修场景
            </div>
            <div className="text-screen-muted text-xs">
              可从历史检修场景中载入，或新建一个检修场景
            </div>
            <button
              onClick={onOpenMaintenancePicker}
              className="mt-2 px-5 py-2 text-sm text-[#40A9FF] border border-[#40A9FF]/60 hover:bg-[#40A9FF]/20 hover:text-white transition-colors rounded-none"
            >
              选择检修场景
            </button>
          </div>
        </div>
      );
    }

    const systemNames = Array.from(
      new Set(maintenanceScene.nodes.map((node) => node.system)),
    );
    const pipeStatusOptions = [
      { label: "带压", color: "#ff4d4f" },
      { label: "不带压", color: "#8c8c8c" },
    ];
    const valveStatusOptions = [
      { label: "开", color: "#52c41a" },
      { label: "关", color: "#8c8c8c" },
      { label: "检修中", color: "#faad14" },
    ];

    return (
      <div className="absolute inset-0">
        <img
          src={panoramaBg}
          alt="检修场景"
          className="w-full h-full object-cover"
          style={{ filter: "brightness(0.5) saturate(0.85)" }}
        />
        <div className="absolute inset-0" style={{ background: "rgba(7, 11, 20, 0.62)" }} />
        <div className="scene-grid absolute inset-0 opacity-15" />

        {/* 场景信息 */}
        <div className="absolute top-[4%] left-1/2 -translate-x-1/2 text-center z-10">
          <div
            className="text-white text-base font-bold tracking-widest px-4 py-1"
            style={{
              textShadow: "0 0 10px rgba(64,169,255,0.8)",
              borderBottom: "1px solid rgba(64,169,255,0.3)",
            }}
          >
            {maintenanceScene.name}
          </div>
          <div className="text-[#40A9FF]/70 text-xs mt-1">
            {maintenanceScene.createdAt} · {maintenanceScene.createdBy} ·{" "}
            {maintenanceScene.nodes.length} 个检修对象
          </div>
        </div>

        {/* 重新选择场景 */}
        <div className="absolute top-3 right-3 z-10">
          <button
            onClick={onOpenMaintenancePicker}
            className="px-3 py-1.5 text-xs text-[#40A9FF] bg-black/60 border border-[#40A9FF]/50 hover:bg-[#40A9FF]/20 hover:text-white transition-colors rounded-none backdrop-blur-sm"
          >
            重新选择
          </button>
        </div>

        {/* 选中对象模型 + 状态立牌 */}
        <div className="absolute inset-0 flex items-center justify-center px-8 pt-[9%] pb-16 overflow-auto z-[5]">
          <div className="flex flex-wrap items-start justify-center gap-4 max-w-[94%]">
            {systemNames.map((system) => {
              const systemColor = getMaintenanceSystemColor(system);
              const nodes = maintenanceScene.nodes.filter(
                (node) => node.system === system,
              );
              return (
                <div
                  key={system}
                  className="bg-black/45 border backdrop-blur-sm px-4 py-3"
                  style={{ borderColor: `${systemColor}66` }}
                >
                  <div className="flex items-center gap-2 mb-2">
                    <span
                      className="w-1.5 h-3.5"
                      style={{ background: systemColor, boxShadow: `0 0 6px ${systemColor}` }}
                    />
                    <span className="text-xs text-white font-medium">{system}</span>
                    <span className="text-[10px] text-screen-muted">
                      ({nodes.length})
                    </span>
                  </div>
                  <div className="flex flex-wrap justify-center gap-x-8 gap-y-5">
                    {nodes.map((node) => {
                      const statusMeta = getMaintenanceStatusMeta(
                        node.kind,
                        node.status,
                      );
                      const statusColor = statusMeta.color;
                      return (
                        <div
                          key={node.key}
                          className="flex flex-col items-center cursor-pointer group"
                          onClick={() => handlePipelineClick(node.title)}
                        >
                          {/* 状态立牌 */}
                          <div className="flex flex-col items-center">
                            <div
                              className="px-2.5 py-1 text-xs font-medium transition-transform group-hover:-translate-y-0.5"
                              style={{
                                color: "#fff",
                                background: `linear-gradient(180deg, ${statusColor}cc, ${statusColor}55)`,
                                border: `1px solid ${statusColor}`,
                                boxShadow: `0 0 10px ${statusColor}88`,
                              }}
                            >
                              {statusMeta.label}
                            </div>
                            <div
                              className="w-px h-3"
                              style={{ background: statusColor }}
                            />
                            <div
                              className="w-1.5 h-1.5 rotate-45 -mt-[3px]"
                              style={{ background: statusColor }}
                            />
                          </div>

                          {/* 模型 */}
                          {node.kind === "pipe" ? (
                            <div
                              className="relative mt-1 w-40 h-5 transition-transform group-hover:scale-105"
                              style={{
                                background: `linear-gradient(180deg, ${systemColor}66, ${systemColor}22)`,
                                border: `1px solid ${systemColor}`,
                                boxShadow: `0 0 12px ${statusColor}55`,
                              }}
                            >
                              <div
                                className="absolute inset-y-1 left-1 right-1"
                                style={{ background: `${systemColor}55` }}
                              />
                              <div
                                className="absolute left-0 top-1/2 -translate-y-1/2 w-1.5 h-5"
                                style={{ background: systemColor }}
                              />
                              <div
                                className="absolute right-0 top-1/2 -translate-y-1/2 w-1.5 h-5"
                                style={{ background: systemColor }}
                              />
                            </div>
                          ) : (
                            <div
                              className="relative mt-1 w-12 h-12 flex items-center justify-center transition-transform group-hover:scale-110"
                              style={{
                                border: `2px solid ${systemColor}`,
                                background: `${systemColor}26`,
                                boxShadow: `0 0 12px ${statusColor}55`,
                                borderRadius: "50%",
                              }}
                            >
                              <Wrench size={18} style={{ color: systemColor }} />
                              <span
                                className="absolute w-2 h-2 rounded-full"
                                style={{
                                  top: -3,
                                  right: -3,
                                  background: statusColor,
                                  boxShadow: `0 0 6px ${statusColor}`,
                                }}
                              />
                            </div>
                          )}

                          <div className="mt-2 text-xs text-white text-center max-w-[180px]">
                            {node.title}
                          </div>
                          <div className="text-[10px] text-screen-muted">
                            {node.code}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* 状态图例 */}
        <div className="absolute bottom-16 right-3 z-10 bg-black/60 border border-[#40A9FF]/30 backdrop-blur-sm p-2.5">
          <div className="text-[10px] text-[#40A9FF]/70 mb-1.5">状态图例</div>
          <div className="flex items-center gap-2 text-[10px] mb-1">
            <span className="w-8 text-screen-muted">管路</span>
            {pipeStatusOptions.map((item) => (
              <span key={item.label} className="flex items-center gap-1" style={{ color: item.color }}>
                <span
                  className="w-3 h-1.5"
                  style={{ background: item.color, boxShadow: `0 0 4px ${item.color}` }}
                />
                {item.label}
              </span>
            ))}
          </div>
          <div className="flex items-center gap-2 text-[10px]">
            <span className="w-8 text-screen-muted">阀门</span>
            {valveStatusOptions.map((item) => (
              <span key={item.label} className="flex items-center gap-1" style={{ color: item.color }}>
                <span
                  className="w-2 h-2 rounded-full"
                  style={{ background: item.color, boxShadow: `0 0 4px ${item.color}` }}
                />
                {item.label}
              </span>
            ))}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="flex-1 relative scene-placeholder overflow-hidden">
      {/* 3D 场景占位 - 模拟UE5渲染画面 */}
      <div className="absolute inset-0">
        {/* 网格背景 */}
        <div className="scene-grid" />

        {/* 扫描线 */}
        <div className="scan-line" />

        {/* 场景切换过渡动画 */}
        {sceneTransition && (
          <div className="absolute inset-0 z-30 flex items-center justify-center bg-black/60 backdrop-blur-sm transition-opacity">
            <div className="text-center">
              <div className="inline-block w-12 h-12 border-3 border-blue-500 border-t-transparent rounded-full animate-spin mb-3" />
              <div className="text-cyan-300 text-sm font-medium">
                正在切换到{viewMode === "overview" ? "工程总览" : focusMode === "equipment" ? "设备总览" : focusMode === "pipeline" ? "管路总览" : "厂房全景"}...
              </div>
              <div className="text-blue-400/50 text-xs mt-1">UE5 像素流场景渲染中</div>
            </div>
          </div>
        )}

        {/* 根据场景渲染不同内容 */}
        {viewMode === "overview" && renderOverviewScene()}
        {viewMode === "interior" && focusMode !== "maintenance" && renderFusionScene()}
        {viewMode === "interior" && focusMode === "maintenance" && renderMaintenanceScene()}

        {/* 选中设备高亮框（检修场景使用立牌标注，不显示居中高亮框） */}
        {selectedNode && focusMode !== "maintenance" && (
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-32 h-32 border-2 border-blue-500 rounded-noneanimate-glow pointer-events-none">
            <div className="absolute -top-6 left-0 text-xs text-blue-400 bg-black/60 px-2 py-0.5 rounded-nonewhitespace-nowrap">
              {selectedNode.title}
            </div>
            {/* 四角标记 */}
            <div className="absolute -top-1 -left-1 w-3 h-3 border-t-2 border-l-2 border-blue-400" />
            <div className="absolute -top-1 -right-1 w-3 h-3 border-t-2 border-r-2 border-blue-400" />
            <div className="absolute -bottom-1 -left-1 w-3 h-3 border-b-2 border-l-2 border-blue-400" />
            <div className="absolute -bottom-1 -right-1 w-3 h-3 border-b-2 border-r-2 border-blue-400" />
          </div>
        )}

        {/* UE5 标识 */}
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 translate-y-[120px] text-center pointer-events-none">
          <p className="text-blue-400/30 text-xs">UE5 Pixel Streaming</p>
        </div>
      </div>

      {/* HUD - 左上角 场景名称 */}
      <DevNote
        id="scene-hud-name"
        title="场景名称HUD（左上角）"
        summary="显示当前场景名与楼层，选中对象时追加对象名称"
        items={[
          { label: "数据来源", value: "getCurrentSceneName()：interior 下按 focusMode+activeFloor 组合（如 厂房全景 - 发电机层），overview 下固定“工程总览”；选中对象后显示“场景名 - 对象名”" },
          { label: "交互逻辑", value: "纯展示；随顶部导航、楼层切换、对象选中实时变化" },
          { label: "后续步骤", value: "正式系统：场景名由 UE5 场景状态回调同步" },
          { label: "权限", value: "大屏所有已登录用户可见" },
        ]}
        wrapClassName="absolute top-3 left-3 z-10"
      >
      <div>
        <div className="bg-black/60 text-white text-sm px-3 py-1 rounded-nonebackdrop-blur-sm">
          {selectedNode
            ? `${getCurrentSceneName().split(" - ")[0]} - ${selectedNode.title}`
            : getCurrentSceneName()}
        </div>
      </div>
      </DevNote>

      {/* HUD - 左下角 操作提示 */}
      <DevNote
        id="scene-hud-hint"
        title="操作提示HUD（左下角）"
        summary="相机操作说明与运行状态（FPS/漫游/录制）"
        items={[
          { label: "数据来源", value: "fps 由 setInterval 每2秒在 58~62 间随机；roamingMode（none/free/path）与 recording 状态来自漫游控制" },
          { label: "交互逻辑", value: "提示“左键旋转/右键平移/滚轮缩放”；自由漫游时追加“WASD 控制移动”；状态区显示 FPS 与 自由漫游中/路径漫游中/路径录制中/静止" },
          { label: "后续步骤", value: "正式系统：FPS 由像素流性能统计回调；操作说明为固定文案" },
          { label: "权限", value: "大屏所有已登录用户可见" },
        ]}
        wrapClassName="absolute bottom-3 left-3 z-10"
      >
      <div>
        <div className="text-screen-muted text-xs bg-black/40 px-2 py-1 rounded-nonebackdrop-blur-sm">
          左键拖拽旋转视角，右键拖拽平移，滚轮缩放
          {roamingMode === "free" && " | WASD 控制移动"}
          <span className="ml-3 text-[#40A9FF]/70">
            FPS: {fps} · {roamingMode === "free" ? "自由漫游中" : roamingMode === "path" ? "路径漫游中" : recording ? "路径录制中" : "静止"}
          </span>
        </div>
      </div>
      </DevNote>

      {/* HUD - 右下角 视角控制按钮组 */}
      <DevNote
        id="scene-hud-camera"
        title="视角控制按钮组（右下角）"
        summary="重置视角、全屏、截图三个快捷操作"
        items={[
          { label: "重置视角", value: "点击提示“相机将平滑返回当前场景默认观察点，恢复初始朝向、缩放比例和旋转中心”（原型 message 占位）" },
          { label: "全屏", value: "document.fullscreenElement 存在则 exitFullscreen()，否则 requestFullscreen()（原生浏览器全屏 API）" },
          { label: "截图", value: "点击提示“截取当前UE5三维视角及数据标注，按场景名称和时间生成图片文件”（原型 message 占位）" },
          { label: "权限", value: "大屏所有已登录用户可用" },
          { label: "后续步骤", value: "正式系统：重置视角由 UE5 相机服务执行；截图由像素流抓帧导出" },
        ]}
        wrapClassName="absolute bottom-3 right-3 z-10"
      >
      <div className="flex gap-2">
        <button
          onClick={() =>
            message.info(
              "实际项目中：相机将平滑返回当前场景的默认观察点，并恢复初始朝向、缩放比例和旋转中心。"
            )
          }
          className="w-9 h-9 bg-black/60 text-white rounded-noneflex items-center justify-center hover:bg-blue-600 transition-colors"
          title="重置视角"
        >
          <Camera size={16} />
        </button>
        <button
          onClick={() => {
            if (document.fullscreenElement) {
              document.exitFullscreen();
            } else {
              document.documentElement.requestFullscreen();
            }
          }}
          className="w-9 h-9 bg-black/60 text-white rounded-noneflex items-center justify-center hover:bg-blue-600 transition-colors"
          title="全屏"
        >
          <Maximize2 size={16} />
        </button>
        <button
          onClick={() =>
            message.info(
              "实际项目中：将截取当前UE5三维视角及数据标注，并按场景名称和时间生成图片文件。"
            )
          }
          className="w-9 h-9 bg-black/60 text-white rounded-noneflex items-center justify-center hover:bg-blue-600 transition-colors"
          title="截图"
        >
          <ImageIcon size={16} />
        </button>
      </div>
      </DevNote>

      {/* 右侧浮动工具栏 - 3D模型操作工具（检修场景下只展示选中对象，隐藏模型工具栏） */}
      {focusMode !== "maintenance" && (
      <DevNote
        id="scene-toolbar"
        title="3D模型操作工具栏（右侧）"
        summary="显隐切换 / 透明度选择 / 水流开关，支持单个模型与整系统批量控制；另有漫游与重置"
        items={[
          { label: "模型控制", value: "三个按钮：是否显示、透明度（100%/60%/30% 循环）、水流效果开关；需先在三维视口或左侧结构树中选择对象" },
          { label: "单个模型", value: "选中设备或管件 → 只作用于自身；隐藏、透明度、水流均实时生效" },
          { label: "按系统批量", value: "在结构树选中系统/分组节点（如某台机组下的供水系统）→ 按钮同样出现，批量控制该系统下所有模型的显隐、透明度与水流" },
          { label: "水流规则", value: "取消全局水流开关，只能按单个模型或按系统开启；默认全部静止，开启后对应管路才渲染流动动画" },
          { label: "漫游控制", value: "自由漫游：WASD移动/鼠标转向/滚轮调速；路径漫游：打开路径列表弹窗，播放默认或自定义路径；录制中显示红色“停止录制”，停止后生成“自定义路线N”并保存" },
          { label: "重置", value: "恢复全部模型显示与默认透明度（水流开关需单独关闭）" },
          { label: "数据来源", value: "hiddenNames/opacityMap 为三维场景本地状态；waterOnSystems 由 Screen 持有，与右侧运行状态卡片共用；pathList 来自 useRoamingPaths()" },
          { label: "后续步骤", value: "正式系统：显隐与透明度通过模型实例属性控制；水流由流量测点驱动，流量为 0 时自动静止" },
        ]}
        wrapClassName="absolute right-3 top-1/2 -translate-y-1/2 z-10"
      >
      <div className="flex flex-col gap-1.5 p-1.5 rounded-none bg-black/60 backdrop-blur-sm border border-screen-border">
        <button
          onClick={handleToggleVisible}
          title={
            !hasTarget
              ? "请先选择对象或系统"
              : allTargetsVisible
                ? selection.isGroup
                  ? "隐藏该系统全部模型"
                  : "隐藏"
                : "显示"
          }
          className={`w-9 h-9 flex items-center justify-center transition-colors ${
            !hasTarget
              ? "text-screen-muted opacity-40 cursor-not-allowed"
              : allTargetsVisible
                ? "text-screen-text hover:bg-gray-700"
                : "bg-blue-600 text-white"
          }`}
        >
          {allTargetsVisible ? <Eye size={18} /> : <EyeOff size={18} />}
        </button>
        <button
          onClick={handleCycleOpacity}
          title={hasTarget ? "透明度（100% / 60% / 30%）" : "请先选择对象或系统"}
          className={`flex h-11 w-9 flex-col items-center justify-center gap-0.5 transition-colors ${
            !hasTarget
              ? "text-screen-muted opacity-40 cursor-not-allowed"
              : currentOpacity < 1
                ? "bg-blue-600 text-white"
                : "text-screen-text hover:bg-gray-700"
          }`}
        >
          <CircleDashed size={15} />
          <span className="text-[8px] leading-none">
            {Math.round(currentOpacity * 100)}%
          </span>
        </button>
        <button
          onClick={handleToggleWater}
          title={
            !hasTarget
              ? "请先选择对象或系统"
              : !selection.systemName
                ? "该对象无水流效果"
                : waterOn
                  ? "关闭水流"
                  : "开启水流"
          }
          className={`w-9 h-9 flex items-center justify-center transition-colors ${
            !hasTarget || !selection.systemName
              ? "text-screen-muted opacity-40 cursor-not-allowed"
              : waterOn
                ? "bg-cyan-600 text-white"
                : "text-screen-text hover:bg-gray-700"
          }`}
        >
          <Droplets size={18} />
        </button>
        <div className="w-full h-px bg-screen-border my-0.5" />
        <button
          onClick={handleFreeRoam}
          title={roamingMode === "free" ? "退出自由漫游" : "自由漫游"}
          className={`w-9 h-9 rounded-none flex items-center justify-center transition-colors ${
            roamingMode === "free"
              ? "bg-cyan-600 text-white"
              : "text-screen-text hover:bg-gray-700"
          }`}
        >
          <Play size={18} />
        </button>
        <button
          onClick={() => setShowPathModal(true)}
          title="路径漫游"
          className={`w-9 h-9 rounded-none flex items-center justify-center transition-colors ${
            roamingMode === "path" || recording
              ? "bg-cyan-600 text-white"
              : "text-screen-text hover:bg-gray-700"
          }`}
        >
          <Map size={18} />
        </button>
        {(roamingMode !== "none" || recording) && (
          <button
            onClick={recording ? handleStopRecord : handleStopRoam}
            title={recording ? "停止录制" : "停止漫游"}
            className="w-9 h-9 rounded-none flex items-center justify-center bg-red-600/80 text-white hover:bg-red-600 transition-colors"
          >
            <Square size={16} />
          </button>
        )}
        <div className="w-full h-px bg-screen-border my-0.5" />
        <button
          onClick={handleResetTools}
          title="重置"
          className="w-9 h-9 rounded-noneflex items-center justify-center text-screen-text hover:bg-red-600 hover:text-white transition-colors"
        >
          <RotateCcw size={18} />
        </button>
      </div>
      </DevNote>
      )}

      {/* 漫游路径列表弹窗 */}
      <DevNote
        id="scene-roaming-modal"
        title="漫游路径管理弹窗"
        summary="查看/播放/编辑/删除漫游路径，并支持录制生成自定义路线"
        items={[
          { label: "数据来源", value: "pathList 来自 useRoamingPaths()（localStorage 持久化），与后台“漫游路线”管理页共享同一份数据；录制生成的路线同样写入该存储" },
          { label: "交互逻辑", value: "播放：进入 path 漫游模式并按关键帧自动飞行；编辑：仅自定义路径提供，点击提示打开编辑窗口（改名称/途经点/朝向/停留时长/速度）；删除：弹确认框，仅自定义路径可删" },
          { label: "录制流程", value: "footer 在录制中显示橙色“停止录制”，否则显示“新建路径”；录制开始后在三维视口内 WASD 移动记录相机轨迹，停止后生成自定义路线并保存" },
          { label: "权限", value: "大屏所有已登录用户可用（浏览人员不可修改漫游路径——原型未限制，正式系统按角色控制）" },
          { label: "后续步骤", value: "正式系统：路径数据持久化到服务端并支持多人共享；浏览人员仅可播放不可编辑" },
        ]}
      >
      <Modal
        open={showPathModal}
        onClose={() => setShowPathModal(false)}
        title="漫游路径管理"
        width={500}
        footer={
          <>
            {recording ? (
              <button
                onClick={handleStopRecord}
                className="flex items-center gap-1 px-4 py-1.5 rounded-nonetext-sm bg-orange-600 text-white hover:bg-orange-700"
              >
                <Square size={14} />
                停止录制
              </button>
            ) : (
              <button
                onClick={handleStartRecord}
                className="flex items-center gap-1 px-4 py-1.5 rounded-nonetext-sm bg-admin-primary text-white hover:bg-blue-600"
              >
                <Plus size={14} />
                新建路径
              </button>
            )}
            <button
              className="btn-default"
              onClick={() => setShowPathModal(false)}
            >
              关闭
            </button>
          </>
        }
      >
        <div className="overflow-auto" style={{ maxHeight: 300 }}>
          <table className="w-full text-sm">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-3 py-2 text-left text-admin-muted border-b">序号</th>
                <th className="px-3 py-2 text-left text-admin-muted border-b">路径名称</th>
                <th className="px-3 py-2 text-left text-admin-muted border-b">类型</th>
                <th className="px-3 py-2 text-left text-admin-muted border-b">创建时间</th>
                <th className="px-3 py-2 text-left text-admin-muted border-b">时长</th>
                <th className="px-3 py-2 text-left text-admin-muted border-b">操作</th>
              </tr>
            </thead>
            <tbody>
              {pathList.map((path, index) => (
                <tr key={path.id} className="border-b border-admin-border">
                  <td className="px-3 py-2 text-admin-text">{index + 1}</td>
                  <td className="px-3 py-2 text-admin-text">{path.name}</td>
                  <td className="px-3 py-2">
                    <span
                      className={`text-xs px-2 py-0.5 rounded-none${
                        path.type === "default"
                          ? "bg-blue-50 text-blue-600"
                          : "bg-green-50 text-green-600"
                      }`}
                    >
                      {path.type === "default" ? "默认路线" : "自定义"}
                    </span>
                  </td>
                  <td className="px-3 py-2 text-admin-muted text-xs">
                    {path.createTime}
                  </td>
                  <td className="px-3 py-2 text-admin-text">
                    约{path.duration}秒
                  </td>
                  <td className="px-3 py-2">
                    <div className="flex gap-2">
                      <button
                        onClick={() => handlePlayPath(path)}
                        className="text-admin-primary hover:text-blue-600"
                        title="播放"
                      >
                        <Play size={14} />
                      </button>
                      {path.type === "custom" && (
                        <>
                          <button
                            onClick={() =>
                              message.info(
                                `实际项目中：将打开“${path.name}”编辑窗口，可修改路线名称、途经点、相机朝向、停留时长和播放速度。`
                              )
                            }
                            className="text-admin-primary hover:text-blue-600"
                            title="编辑"
                          >
                            <Pencil size={14} />
                          </button>
                          <button
                            onClick={() => setDeletePathId(path.id)}
                            className="text-admin-danger hover:text-red-600"
                            title="删除"
                          >
                            <Trash2 size={14} />
                          </button>
                        </>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Modal>
      </DevNote>

      {/* 删除确认弹窗 */}
      <DevNote
        id="scene-roaming-delete"
        title="删除路径确认弹窗"
        summary="删除自定义漫游路径前的二次确认"
        items={[
          { label: "触发条件", value: "仅自定义路径（type=custom）行内点击删除按钮 → 记录 deletePathId 并弹出确认框" },
          { label: "交互逻辑", value: "确认 → pathList.filter 移除该路径并提示“路径已删除”；取消 → 关闭弹窗" },
          { label: "数据来源", value: "pathList 来自 useRoamingPaths()，删除后同步写入 localStorage 并通知后台漫游路线页" },
          { label: "权限", value: "大屏所有已登录用户可用" },
        ]}
      >
      <ConfirmModal
        open={deletePathId !== null}
        content="确定删除该漫游路径吗？"
        okText="删除"
        danger
        onConfirm={handleDeletePath}
        onCancel={() => setDeletePathId(null)}
      />
      </DevNote>
    </div>
  );
}
