// 为设备实例按其类型模板生成属性列表
function buildEquipmentAttributes(eq: Equipment): EquipmentAttribute[] {
  const templateKey = attrTypeMap[eq.type] || eq.type;
  const group = equipmentAttrTemplates[templateKey];
  if (!group) return [];
  const attrs: EquipmentAttribute[] = [];
  let attrId = 1;
  group.categories.forEach((cat) => {
    cat.attrs.forEach((attr) => {
      let value = "";
      // 动态填充已知字段
      if (attr.name === "设备名称") value = eq.name;
      else if (attr.name === "KKS编码") value = eq.code;
      else if (attr.name === "唯一编码") value = eq.code;
      else if (attr.name === "编码") value = group.className;
      else if (attr.name === "型号") value = eq.model || attr.defaultValue || "";
      else value = attrSampleValues[attr.name] || attr.defaultValue || "";
      attrs.push({
        id: attrId++,
        equipmentId: eq.id,
        name: attr.name,
        value,
        type: "text" as const,
        unit: attr.unit || "",
        category: cat.name,
      });
    });
  });
  return attrs;
}

// 给每台设备自动生成属性
equipments.forEach((eq) => {
  eq.attributes = buildEquipmentAttributes(eq);
});

// 管路
export const pipelines: Pipeline[] = pipelineData;

const pipeComponentTemplates = [
  { type: "阀门", suffix: "AA", divisor: 70, minimum: 2 },
  { type: "弯头", suffix: "BR", divisor: 35, minimum: 2 },
  { type: "三通", suffix: "AT", divisor: 120, minimum: 1 },
  { type: "异径接头", suffix: "RE", divisor: 160, minimum: 1 },
] as const;

pipelines.forEach((pipeline) => {
  const pipelineLength = pipeline.length || 0;
  pipeline.components = pipeComponentTemplates.map((template, index) => ({
    id: pipeline.id * 100 + index + 1,
    pipelineId: pipeline.id,
    code: `${pipeline.code}-${template.suffix}${String(index + 1).padStart(2, "0")}`,
    name: `${pipeline.name}${template.type}`,
    type: template.type,
    spec: pipeline.dn,
    material: pipeline.material,
    quantity:
      Math.max(template.minimum, Math.ceil(pipelineLength / template.divisor)) +
      (template.type === "阀门" && pipeline.name.includes("阀组") ? 3 : 0),
    designPressure: pipeline.designPressure,
    designTemperature: pipeline.designTemperature,
    medium: pipeline.medium,
    wallThickness: pipeline.wallThickness,
  }));
});

